<script setup lang="ts">import { ref } from 'vue'; import { getUniRuntime } from '../../platform/uni-runtime'; import { mobileGoals, mobileQuotas } from '../../domain/b1'; import { useB1Store } from '../../stores/b1'; const b1=useB1Store(); const goal=ref(b1.state.goal); const quota=ref(b1.state.quota); const consent=ref(false); function save(){if(!goal.value||!consent.value)return;b1.completeOnboarding(goal.value,quota.value);getUniRuntime().navigateTo({url:'/pages/assessment/assessment'})}</script>
<template><view class="yx-page"><text class="yx-eyebrow">FIRST DAY · 1/2</text><text class="yx-title">先定一个适合你的学习起点。</text><text class="yx-description">面向 18 岁以上成人与大学生，目标可以随时修改。</text><view class="yx-card"><text class="section-title">学习目标</text><view class="choice-list"><button v-for="item in mobileGoals" :key="item" :class="['choice', {selected:goal===item}]" @click="goal=item">{{item}}</button></view><text class="section-title">每天投入</text><view class="choice-list"><button v-for="item in mobileQuotas" :key="item" :class="['choice', {selected:quota===item}]" @click="quota=item">{{item}} 分钟</button></view><label class="consent"><checkbox :checked="consent" @click="consent=!consent" />我已确认年满 18 周岁并同意隐私说明</label><button class="yx-button" :disabled="!goal||!consent" @click="save">保存并开始测评</button></view></view></template>
<style scoped>.section-title{display:block;margin:18rpx 0;font-weight:700}.choice-list{display:flex;flex-wrap:wrap;gap:16rpx}.choice{margin:0;padding:16rpx 20rpx;border:1rpx solid #e6e8f0;border-radius:14rpx;color:#202332;background:#fff;font-size:26rpx}.choice.selected{border-color:#596bff;color:#596bff;background:#eef0ff}.consent{display:flex;align-items:center;margin-top:24rpx;color:#666d80;font-size:24rpx}</style>
